def _missing_fill_variable(name, fill_value, datasets):
    """Create a fill variable for a missing variable in a dataset.

    Determines the appropriate dtype and fill value by looking at the variable
    in other datasets that do have it.
    """
    # Find the variable in any dataset that has it to get its dtype
    for ds in datasets:
        if name in ds.variables:
            var = ds.variables[name]
            break
    else:
        raise ValueError("Variable %r not found in any dataset" % name)

    if fill_value is dtypes.NA:
        _, fv = dtypes.maybe_promote(var.dtype)
    else:
        fv = fill_value

    return Variable((), fv)


